package com.ramy.mindgame.core
import com.ramy.mindgame.games.*
import org.json.JSONObject

data class GameInfo(val id: String, val name: String, val category: String, val subtitle: String, val color: String, val rules: String, val create: ()->Game, val load: (JSONObject)->Game)
object Registry {
    val games=listOf(
        GameInfo("enigma","Solve the Enigma","DEDUCTION","Read the clues. Find the code.","#73C4B3","GOAL\nFind a secret four-digit code. All four digits are different; 0 can be first.\n\nRULES\nEach clue describes its own code. “Right” counts digits in the correct slot; “misplaced” counts correct digits in other slots. Any digits not counted are absent. Every clue is exact.\n\nEXAMPLE\nIf a clue has 2 correct digits, 1 right: one digit is correctly placed and one belongs elsewhere.\n\nPLAY\nTap a slot, then a number key. Use candidates and scratch-outs to rule out codes; hold a key to eliminate a digit. Submit with DECIPHER. You have 3 guesses. HINT helps; RESOLVE reveals the answer.",{ CodeGame("enigma") },CodeGame::load),
        GameInfo("sudoku","Sudoku","LOGIC","Nine digits. One perfect fit.","#DBBC72","GOAL\nFill the grid so every row, column and 3×3 box contains 1–9 once each.\n\nRULES\nPrinted clues cannot change. A digit must fit all three groups, not just its row. Red entries conflict with another digit.\n\nEXAMPLE\nIf a row lacks 2 and 7, check the column and box to decide which fits.\n\nPLAY\nTap a cell, then a digit. Notes stores possible digits; Erase clears an entry. Undo reverses an edit. Hint fills one empty cell. Choose Easy, Medium, Hard or Expert. Complete the valid grid to win.",{ SudokuGame() },SudokuGame::load),
        GameInfo("mines","Minesweeper","STRATEGY","A little risk. A lot of logic.","#DAB15A","GOAL\nOpen every safe square without opening a mine.\n\nRULES\nA number counts mines in the eight surrounding squares, including diagonals. Empty regions open together. Flags are reminders, not proof. Your first opening and its neighbors are safe.\n\nEXAMPLE\nA 1 touching just one unopened square means that square contains a mine.\n\nPLAY\nTap to reveal; hold to flag, or switch to Flag mode. Tap a revealed number after flagging its neighbors to open the others—wrong flags can lose the game. Drag and pinch larger boards. Choose 10, 40, 99 mines or Custom.",{ MinesGame() },MinesGame::load),
        GameInfo("mastermind","Mastermind","DEDUCTION","Four colors. Crack the pattern.","#D4B173","GOAL\nDiscover the hidden four-color code within 10 guesses. Colors may repeat.\n\nRULES\nA red feedback peg means correct color and position. An ivory peg means correct color, wrong position. Blank sockets mean no further matches. Feedback is a count; its positions do not identify your pegs.\n\nEXAMPLE\n2 red + 1 ivory means two colors are correctly placed and another belongs in a different slot.\n\nPLAY\nTap a palette color to fill the next slot. Tap a guess slot to replace it, then choose its color directly. Submit a complete row. Compare feedback across guesses. Four red pegs wins.",{ CodeGame("mastermind") },CodeGame::load),
        GameInfo("memory","Relic Hunt","MEMORY","Find your rhythm. Match the pairs.","#73C4B3","GOAL\nUncover every matching pair of relics.\n\nRULES\nTurn over two different cards per turn. A match stays face up; a mismatch turns back after a short pause. Remember both the relic and its location.\n\nEXAMPLE\nIf you uncover a compass you saw earlier, select its remembered partner.\n\nPLAY\nTap cards to reveal them. Choose 6, 8, 12 or 16 pairs for a larger hunt. There is no turn limit. Finding all pairs wins; fewer turns improves your score. Progress saves when you leave.",{ MemoryGame() },MemoryGame::load),
        GameInfo("2048","2048","NUMBERS","Slide. Combine. Think ahead.","#DE9A60","GOAL\nMerge tiles to make 2048, then continue toward 4096 and beyond.\n\nRULES\nSwipe moves all tiles in that direction. Equal neighbors merge into double their value, once per move. A valid move adds a new 2 or 4. Each merge adds its new value to your score.\n\nEXAMPLE\n2 + 2 makes 4. In a row of 2, 2, 2, 2, one swipe makes 4, 4—not 8.\n\nPLAY\nSwipe the board; Undo reverses your last move. Keep empty spaces and plan ahead. Milestones are 512, 1024, 2048 and 4096. The run ends when the full board has no adjacent equal tiles.",{ TilesGame() },TilesGame::load),
        GameInfo("nonogram","Mosaic Restoration","PICTURE LOGIC","Turn number clues into a picture.","#73C4B3","GOAL\nUse row and column clues to reveal a hidden mosaic picture.\n\nRULES\nEach number describes a consecutive filled group, in order. Separate groups by at least one empty square. A 0 means the whole line is empty. Cross squares you know are empty.\n\nEXAMPLE\n3, 1 means three filled squares together, at least one gap, then one filled square. Extra empty squares may appear before, between or after groups.\n\nPLAY\nChoose Fill or Mark ×, then tap or drag. Pan mode and pinch zoom help on larger boards. Completed lines dim their clues. Undo reverses a stroke. Restore 10×10, 15×15 or 20×20 pictures and collect them.",{ NonogramGame() },NonogramGame::load)
    )
    fun get(id: String)=games.first { it.id==id }
}
